import xlrd
wb = xlrd.open_workbook('/root/data/external-data.xls')
print("Sheet names:", wb.sheet_names())
for sname in wb.sheet_names():
    ws = wb.sheet_by_name(sname)
    print(f"\n=== Sheet: {sname} (rows={ws.nrows}, cols={ws.ncols}) ===")
    for r in range(min(5, ws.nrows)):
        row_vals = []
        for c in range(min(15, ws.ncols)):
            v = ws.cell_value(r, c)
            if v:
                row_vals.append((c, v))
        if row_vals:
            print(f"Row {r}: {row_vals}")
